INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('690f82c8-60c1-4876-81ea-db828cbb8172', '0b8ddab7-b106-4873-bc4d-3987421d265d', 4, 'A Alimentação da Alma', NULL, '{"intro": "O que voc\u00ea l\u00ea, assiste e ouve molda a sua percep\u00e7\u00e3o da realidade.", "prayer": "Pe\u00e7a discernimento para o que voc\u00ea deixa entrar pelos olhos.", "practice": "Leia 5 p\u00e1ginas de um livro espiritual em vez de rolar as redes sociais.", "reflection": "Voc\u00ea se torna o que voc\u00ea consome.", "journal_prompt": "Como est\u00e1 a sa\u00fade da sua alma hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;